public class DatasetUtilities_iterateDomainBounds_TriageGen0Test {

    @Test(expected = IllegalArgumentException.class)
    public void testIterateDomainBounds_NullDataset() {
        DatasetUtilities.iterateDomainBounds(null, true);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_IncludeIntervalFalse() {
        // When includeInterval is false, the code loops from series = 1 (skipping series 0)
        XYDataset mockDataset = mock(XYDataset.class);
        when(mockDataset.getSeriesCount()).thenReturn(2);
        when(mockDataset.getItemCount(1)).thenReturn(1);
        when(mockDataset.getXValue(1, 0)).thenReturn(10.0);

        Range range = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertNotNull(range);
        assertEquals(10.0, range.getLower(), 1e-9);
        assertEquals(10.0, range.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_IncludeIntervalFalse_Empty() {
        XYDataset mockDataset = mock(XYDataset.class);
        when(mockDataset.getSeriesCount()).thenReturn(1); // Only series 0 exists, loop starts at 1

        Range range = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertNull(range);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeIntervalTrue() {
        IntervalXYDataset mockIntervalDataset = mock(IntervalXYDataset.class);
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(1);

        // Test values: X=5, Start=2, End=8
        when(mockIntervalDataset.getXValue(0, 0)).thenReturn(5.0);
        when(mockIntervalDataset.getStartXValue(0, 0)).thenReturn(2.0);
        when(mockIntervalDataset.getEndXValue(0, 0)).thenReturn(8.0);

        Range range = DatasetUtilities.iterateDomainBounds(mockIntervalDataset, true);

        assertNotNull(range);
        assertEquals(2.0, range.getLower(), 1e-9);
        assertEquals(8.0, range.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeIntervalTrue_WithNaN() {
        IntervalXYDataset mockIntervalDataset = mock(IntervalXYDataset.class);
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(2);

        // Item 0: X=10, Start=NaN, End=20
        when(mockIntervalDataset.getXValue(0, 0)).thenReturn(10.0);
        when(mockIntervalDataset.getStartXValue(0, 0)).thenReturn(Double.NaN);
        when(mockIntervalDataset.getEndXValue(0, 0)).thenReturn(20.0);

        // Item 1: X=NaN, Start=5, End=NaN
        when(mockIntervalDataset.getXValue(0, 1)).thenReturn(Double.NaN);
        when(mockIntervalDataset.getStartXValue(0, 1)).thenReturn(5.0);
        when(mockIntervalDataset.getEndXValue(0, 1)).thenReturn(Double.NaN);

        Range range = DatasetUtilities.iterateDomainBounds(mockIntervalDataset, true);

        assertNotNull(range);
        assertEquals(5.0, range.getLower(), 1e-9);
        assertEquals(20.0, range.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeIntervalTrue_AllNaN() {
        IntervalXYDataset mockIntervalDataset = mock(IntervalXYDataset.class);
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(1);
        when(mockIntervalDataset.getXValue(0, 0)).thenReturn(Double.NaN);
        when(mockIntervalDataset.getStartXValue(0, 0)).thenReturn(Double.NaN);
        when(mockIntervalDataset.getEndXValue(0, 0)).thenReturn(Double.NaN);

        Range range = DatasetUtilities.iterateDomainBounds(mockIntervalDataset, true);

        assertNull(range);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_IncludeIntervalTrue_NonIntervalDataset() {
        // If includeInterval is true but dataset is NOT an instance of IntervalXYDataset,
        // it falls into the 'else' block.
        XYDataset mockDataset = mock(XYDataset.class);
        when(mockDataset.getSeriesCount()).thenReturn(2);
        when(mockDataset.getItemCount(1)).thenReturn(1);
        when(mockDataset.getXValue(1, 0)).thenReturn(15.0);

        Range range = DatasetUtilities.iterateDomainBounds(mockDataset, true);

        assertNotNull(range);
        assertEquals(15.0, range.getLower(), 1e-9);
        assertEquals(15.0, range.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_IncludeIntervalFalse_WithNaN() {
        XYDataset mockDataset = mock(XYDataset.class);
        when(mockDataset.getSeriesCount()).thenReturn(2);
        when(mockDataset.getItemCount(1)).thenReturn(2);

        // Item 0: 10.0
        when(mockDataset.getXValue(1, 0)).thenReturn(10.0);
        // Item 1: NaN
        when(mockDataset.getXValue(1, 1)).thenReturn(Double.NaN);

        Range range = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertNotNull(range);
        assertEquals(10.0, range.getLower(), 1e-9);
        assertEquals(10.0, range.getUpper(), 1e-9);
    }
}
